    mono_rows, mono_cols = find_mono_lines(grid)

    if not mono_rows and not mono_cols:
        return [row[:] for row in grid]

    # Count lines per value
    mono_by_value = {}
    for r, v in mono_rows.items():
        mono_by_value[v] = mono_by_value.get(v, 0) + 1
    for c, v in mono_cols.items():
        mono_by_value[v] = mono_by_value.get(v, 0) + 1

    # Find value with most mono lines
    primary_value = max(mono_by_value, key=mono_by_value.get)
    count = mono_by_value[primary_value]

    # Transform formula: count // 2
    # Demo: count=4, 4//2=2 ✓
    new_value = count // 2

    # Transform cells in mono rows/cols of primary_value to new_value
    result = [row[:] for row in grid]

    for r in mono_rows:
        if mono_rows[r] == primary_value:
            result[r] = [new_value if grid[r][c] == primary_value else grid[r][c] for c in range(len(grid[r]))]

    for c in mono_cols:
        if mono_cols[c] == primary_value:
            for r in range(len(grid)):
                if grid[r][c] == primary_value:
                    result[r][c] = new_value

    return result

